def solve(n):
    # Условие: после удаления любой кучки все камни (S) делятся поровну на n-1 кучек,
    # значит S делится на (n-1) и S/(n-1) >= M (максимум).
    # Перебираем M и ищем подходящую сумму S для набора из n различных чисел с максимумом M.
    for M in range(1, 10**6):
        if M - 1 < n - 1:
            continue
        lo = max(M + n * (n - 1) // 2, (n - 1) * M)
        hi = M + (n - 1) * (M - 1) - (n - 1) * (n - 2) // 2
        for S in range(lo, hi + 1):
            if S % (n - 1) == 0:
                return M
    return None
